<script setup lang="ts">
import { computed,nextTick,ref,watch } from 'vue'
import { interview,text,ui,structureById } from './content'
import { nextEyeQuestion } from './interview'
import EyeSummary from './EyeSummary.vue'
import EyePainAssessment from './EyePainAssessment.vue'
import EyeCareAdvice from './EyeCareAdvice.vue'
import { knowledgeTopic,learningPrompts,library } from './knowledge'
import type { EyeSession,EyeTurn } from './types'
const props=defineProps<{session:EyeSession;acknowledged:boolean;compact?:boolean}>()
const emit=defineEmits<{answer:[turn:EyeTurn];acknowledge:[value:boolean];reset:[]}>()
const input=ref('')
const logElement=ref<HTMLDivElement>()
watch(()=>props.session.messages.length,async()=>{await nextTick();if(logElement.value)logElement.value.scrollTop=logElement.value.scrollHeight})
const urgencyElement=ref<HTMLElement>()
watch(()=>props.session.urgency,async value=>{if(value!=='unknown'){await nextTick();urgencyElement.value?.focus()}})
const safetyInput=ref('')
const question=computed(()=>nextEyeQuestion(props.session))
const matches=computed(()=>interview.rules.filter(r=>props.session.rule_ids.includes(r.id)))
const locale=computed(()=>props.session.locale)
function send(value?:string){if(!props.acknowledged)return;const answer=value??input.value.trim();if(!answer)return;const topic=knowledgeTopic(answer);if(topic){emit('answer',{question_id:`learn:${topic.id}`,value:answer});input.value='';return}if(!question.value)return;const q=question.value;emit('answer',{question_id:q.id,value:answer,...(!value&&q.options.length?{text:answer}:{})});input.value=''}
function warning(value:string){if(!props.acknowledged||props.session.urgency!=='unknown')return;emit('answer',{question_id:'question.concern',value})}
function safetyUpdate(){if(!safetyInput.value.trim())return;emit('answer',{question_id:'question.concern',value:safetyInput.value.trim()});safetyInput.value=''}
</script>
<template><div class="eye-interview-layout" :class="{'eye-interview-compact':compact}">
 <section class="eye-interview-panel" aria-label="Adaptive eye symptom interview">
  <div class="eye-interview-heading"><div><span class="eye-kicker">{{locale==='en'?'ADAPTIVE EYE INTERVIEW · DRAFT':locale==='ar-IQ'?'محادثة عين تكيفية · مسودة':'گفتوگۆی گونجاوی چاو · ڕەشنووس'}}</span><h3>{{locale==='en'?'Symptom assistant':locale==='ar-IQ'?'مساعد الأعراض':'یاریدەدەری نیشانەکان'}}</h3></div><button @click="emit('reset')">{{text(ui.reset,locale)}}</button></div>
  <p class="eye-subtle">{{text(ui.notDiagnosis,locale)}} {{locale==='en'?'Free text stays in its original language. Lexical recognition is limited; use the explicit safety buttons for these events.':locale==='ar-IQ'?'النص الحر يبقى بلغته الأصلية. التعرف على النص محدود؛ استخدم أزرار الخطر الواضحة لهذه الحالات.':'دەقی ئازاد بە زمانی خۆی دەمێنێتەوە. ناسینەوەی دەق سنووردارە؛ بۆ ئەم ڕووداوانە دوگمەکانی مەترسی بەکاربهێنە.'}}</p>
  <label class="eye-ack"><input type="checkbox" :checked="acknowledged" @change="emit('acknowledge',($event.target as HTMLInputElement).checked)"/><span>{{locale==='en'?'I am using synthetic examples to evaluate this unreviewed educational prototype, not real patient triage.':locale==='ar-IQ'?'أستخدم أمثلة افتراضية لتقييم النموذج التعليمي غير المراجع، مو لتقييم مرضى حقيقيين.':'نموونەی دەستکرد بەکاردەهێنم بۆ هەڵسەنگاندنی ئەم مۆدێلە فێرکارییە پێداچوونەوەنەکراوە، نەک بۆ هەڵسەنگاندنی نەخۆشی ڕاستەقینە.'}}</span></label>
  <div v-if="session.urgency==='unknown'" class="eye-safety-shortcuts"><span>{{locale==='en'?'Interrupt for a safety event':locale==='ar-IQ'?'أوقف المحادثة لحالة خطر':'بۆ ڕووداوێکی مەترسیدار گفتوگۆ بوەستێنە'}}</span><button :disabled="!acknowledged" @click="warning('Sudden loss of vision, no pain')">{{locale==='en'?'Sudden vision loss':locale==='ar-IQ'?'فقدان نظر مفاجئ':'لەدەستدانی لەناکاوی بینین'}}</button><button :disabled="!acknowledged" @click="warning('Chemical splash in the eye')">{{locale==='en'?'Chemical splash':locale==='ar-IQ'?'مادة كيميائية بالعين':'پڕژانی ماددەی کیمیایی'}}</button><button :disabled="!acknowledged" @click="warning('A sharp object pierced my eye')">{{locale==='en'?'Penetrating injury':locale==='ar-IQ'?'جرح نافذ':'برینداریی چوونەناو'}}</button><button :disabled="!acknowledged" @click="warning('New flashes and floaters with a curtain in my vision')">{{locale==='en'?'Flashes / curtain':locale==='ar-IQ'?'ومضات أو ستار':'بروسکە یان پەردە'}}</button></div>
  <div v-if="session.urgency!=='unknown'" ref="urgencyElement" class="eye-urgency" :class="session.urgency" role="alert" tabindex="-1" data-testid="eye-urgency"><span class="eye-kicker">DRAFT EDUCATIONAL SAFETY RESULT</span><h3>{{session.urgency==='emergency'?(locale==='en'?'Emergency assessment now':locale==='ar-IQ'?'فحص طارئ هسه':'پشکنینی فریاکەوتن ئێستا'):(locale==='en'?'Urgent eye assessment today':locale==='ar-IQ'?'فحص عيون عاجل اليوم':'پشکنینی پەلەیی چاو ئەمڕۆ')}}</h3><p>{{text(interview.actions[session.urgency],locale)}}</p><div v-for="rule in matches" :key="rule.id"><strong v-if="rule.first_aid" class="eye-first-aid">{{text(rule.first_aid,locale)}}</strong><p>{{text(rule.reason,locale)}}</p><p v-if="locale!=='en'" lang="en" dir="ltr">{{rule.reason.en}}</p></div><p>{{locale==='en'?'Routine questions have stopped. This is an unreviewed demonstration, not a clinical decision.':locale==='ar-IQ'?'تم إيقاف الأسئلة العادية. هذا عرض غير مراجع، مو قرار طبي.':'پرسیارە ئاساییەکان وەستێنران. ئەمە پیشاندانێکی پێداچوونەوەنەکراوە، بڕیاری پزیشکی نییە.'}}</p></div>
  <EyeCareAdvice v-if="session.turns.some(t=>!t.question_id.startsWith('learn:'))" :session="session"/>
  <form v-if="session.urgency==='urgent'" class="eye-question" @submit.prevent="safetyUpdate"><label for="eye-extra-warning">{{locale==='en'?'Optional additional warning information · do not delay seeking care':locale==='ar-IQ'?'معلومات خطر إضافية اختيارية · لا تأخر طلب الرعاية':'زانیاریی زیادەی مەترسی بە ئارەزوو · داواکردنی چاودێری دوا مەخە'}}</label><div class="eye-answer-input"><input id="eye-extra-warning" v-model="safetyInput" maxlength="2000" dir="auto"/><button type="submit" :disabled="!safetyInput.trim()">{{text(ui.send,locale)}}</button></div></form>
  <div ref="logElement" class="eye-chat-log" role="log" aria-label="Eye interview conversation" aria-live="polite"><div v-for="(message,index) in session.messages" :key="index" class="eye-chat-message" :class="message.role" dir="auto"><span>{{message.role==='assistant'?'◈':'○'}}</span><div><span v-if="message.kind==='education'" class="eye-learning-label">{{locale==='en'?'EDUCATIONAL ANSWER · NOT A DIAGNOSIS':locale==='ar-IQ'?'جواب تعليمي · مو تشخيص':'وەڵامی فێرکاری · نەک دەستنیشانکردن'}}</span><p>{{message.text}}</p><a v-for="url in message.source_urls" :key="url" :href="url" target="_blank" rel="noopener noreferrer" class="eye-chat-source">{{url.replace('https://','').split('/')[0]}} ↗</a></div></div></div>
  <p v-for="(notice,index) in session.acknowledgements" :key="index" class="eye-notice" role="status">{{notice}}</p>
  <form v-if="question" class="eye-question" @submit.prevent="send()"><span class="eye-kicker">{{question.id.replace('question.','').toUpperCase()}}</span><h4>{{text(question.text,locale)}}</h4><div class="eye-quick-answers"><button v-for="o in question.options" :key="o.value" type="button" :disabled="!acknowledged" @click="send(o.value)">{{text(o.label,locale)}}</button><template v-if="question.type==='pain'"><button v-for="n in 11" :key="n" type="button" :disabled="!acknowledged" @click="send(String(n-1))">{{n-1}}</button></template><template v-if="question.field==='concern'"><button v-for="s in interview.symptoms" :key="s.id" type="button" :disabled="!acknowledged" @click="send(s.label.en)">{{text(s.label,locale)}}</button></template></div><label :for="`eye-answer-${question.id}`">{{locale==='en'?'Answer in your own words':locale==='ar-IQ'?'جاوب بكلماتك':'بە وشەکانی خۆت وەڵام بدە'}}</label><div class="eye-answer-input"><input :id="`eye-answer-${question.id}`" v-model="input" :type="['pain','age','days'].includes(question.type)?'number':'text'" :min="['pain','age','days'].includes(question.type)?0:undefined" :max="question.type==='pain'?10:question.type==='age'?120:question.type==='days'?365:undefined" maxlength="2000" :disabled="!acknowledged" dir="auto"/><button type="submit" :disabled="!acknowledged||!input.trim()">{{text(ui.send,locale)}} →</button></div><button type="button" class="eye-skip" :disabled="!acknowledged" @click="emit('answer',{question_id:question.id,value:'unknown'})">{{locale==='en'?'Not sure / skip · stays unknown':locale==='ar-IQ'?'مو متأكد / تخطي · يبقى غير معروف':'دڵنیا نیم / تێپەڕین · نادیار دەمێنێتەوە'}}</button></form>
  <p v-else-if="session.urgency==='unknown'" class="eye-notice">{{text(interview.actions.unknown,locale)}}</p>
  <EyePainAssessment :session="session" :enabled="acknowledged" @answer="emit('answer',$event)"/>
  <details v-if="session.urgency==='unknown'" class="eye-chat-knowledge"><summary>{{locale==='en'?`Ask and learn · ${library.topics.length} topics`:locale==='ar-IQ'?`اسأل وتعلم · ${library.topics.length} موضوع`:`بپرسە و فێربە · ${library.topics.length} بابەت`}}</summary><p>{{locale==='en'?'Ask about an eye structure or condition at any point. Learning answers keep your interview in place.':locale==='ar-IQ'?'اسأل عن تركيب أو حالة بأي وقت. الجواب التعليمي ما يغير أجوبة الأعراض.':'هەر کاتێک لە پێکهاتە یان نەخۆشی بپرسە. وەڵامی فێرکاری وەڵامی نیشانەکان ناگۆڕێت.'}}</p><div class="eye-quick-answers"><button v-for="prompt in learningPrompts[locale]" :key="prompt" :disabled="!acknowledged" @click="send(prompt)">{{prompt}}</button></div><form v-if="!question" class="eye-answer-input" @submit.prevent="send()"><input v-model="input" aria-label="Ask an eye education question" maxlength="2000"/><button :disabled="!acknowledged||!input.trim()">{{text(ui.send,locale)}}</button></form></details>
 </section>
 <div v-if="!compact" class="eye-interview-summary"><div class="eye-location-guide"><span class="eye-kicker">{{locale==='en'?'You do not need anatomy knowledge':locale==='ar-IQ'?'ما تحتاج تعرف التشريح':'پێویستت بە زانیاریی پێکهاتەی چاو نییە'}}</span><p>{{interview.locations.map(l=>l.label[locale]).join(' · ')}}</p><small>{{locale==='en'?'Explored:':locale==='ar-IQ'?'المستكشف:':'گەڕاو:'}} {{structureById.get(session.anatomy_explored.at(-1)||'')?.label[locale]||'—'}}</small></div><EyeSummary :session="session"/></div>
</div></template>
